// ARVpnClientFieldFromValueOK mirrors `ARVpnClientField.from_value` without the UNKNOWN fallback.
func ARVpnClientFieldFromValueOK(value any) (ARVpnClientField, bool) {
	switch v := value.(type) {
	case ARVpnClientField:
		return v, v.Valid()
	case *ARVpnClientField:
		if v != nil {
			return *v, v.Valid()
		}
	}
	if vstr := converters.RawToStr(value); vstr != nil {
		if m := ARVpnClientField(*vstr); m.Valid() {
			return m, true
		}
		if m, ok := aRVpnClientFieldByName[strings.ToUpper(*vstr)]; ok {
			return m, true
		}
	}
	var zero ARVpnClientField
	return zero, false
}

// ARVpnClientFieldFromValue mirrors `ARVpnClientField.from_value`: unresolved values map to ARVpnClientFieldUnknown.
func ARVpnClientFieldFromValue(value any) ARVpnClientField {
	if m, ok := ARVpnClientFieldFromValueOK(value); ok {
		return m
	}
	return ARVpnClientFieldUnknown
}
